final class CheckoutService
{
    public function __construct(
        private readonly StockReserver $stock,
        private readonly PaymentGateway $gateway,
        private readonly Stopwatch $stopwatch,
        private readonly LoggerInterface $logger,
    ) {
    }

    public function checkout(Cart $cart): Receipt
    {
        $this->stopwatch->start('stock');
        $this->stock->reserve($cart);                 // database work
        $stockMs = $this->stopwatch->stop('stock')->getDuration();

        $this->stopwatch->start('payment');
        $receipt = $this->gateway->charge($cart);     // outside API
        $paymentMs = $this->stopwatch->stop('payment')->getDuration();

        $this->logger->info('checkout.timing', [
            'stock_ms' => $stockMs,
            'payment_ms' => $paymentMs,
        ]);

        return $receipt;
    }
}

