apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata: {name: shop-app}
spec:
  scaleTargetRef: {apiVersion: apps/v1, kind: Deployment, name: shop-app}
  minReplicas: 6          # kept ready in advance for the known busy hours
  maxReplicas: 20
  metrics:
    - type: Resource
      resource:
        name: cpu
        target: {type: Utilization, averageUtilization: 60}
  behavior:
    scaleUp:   {stabilizationWindowSeconds: 0}
    scaleDown: {stabilizationWindowSeconds: 300}

vrrp_script chk_nginx {
    script "/usr/bin/pgrep nginx"   # unhealthy if nginx is not running
    interval 2
    fall 2                          # 2 failures in a row = give up the IP
}

vrrp_instance shop_vip {
    state MASTER                    # on LB B write: state BACKUP
    interface eth0
    virtual_router_id 51            # must be the same on both boxes
    priority 150                    # on LB B write 100; higher number wins
    advert_int 1                    # heartbeat every second
    virtual_ipaddress {
        203.0.113.10/24             # the one address DNS points to
    }
    track_script {
        chk_nginx
    }
}

upstream shop_app {
    least_conn;                       # give it to whoever has the least work
    server 10.0.1.11:8080 weight=3 max_fails=3 fail_timeout=10s;
    server 10.0.1.12:8080 weight=3 max_fails=3 fail_timeout=10s;
    server 10.0.1.13:8080 weight=1 max_fails=3 fail_timeout=10s;  # older, smaller
    server 10.0.1.20:8080 backup;     # only when everyone else is down
    keepalive 32;
}

server {
    listen 80;
    location / {
        proxy_pass http://shop_app;
        proxy_http_version 1.1;
        proxy_set_header Connection '';
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_next_upstream error timeout http_502 http_503;
        proxy_next_upstream_tries 2;
    }
}

