final class HashRing
{
    /** @var array<int, string> position => node, kept sorted */
    private array $ring = [];
    private array $positions = [];       // the same positions, as a list

    public function __construct(private readonly int $vnodes = 150) {}

    public function add(string $node, float $weight = 1.0): void
    {
        $count = (int) round($this->vnodes * $weight);
        for ($i = 0; $i < $count; $i++) {
            $this->ring[crc32($node.'#'.$i)] = $node;
        }
        ksort($this->ring);
        $this->positions = array_keys($this->ring);
    }

    public function remove(string $node): void
    {
        $this->ring = array_filter($this->ring, fn (string $n) => $n !== $node);
        $this->positions = array_keys($this->ring);
    }

    public function nodeFor(string $key): string
    {
        $h = crc32($key);
        [$lo, $hi] = [0, count($this->positions)];
        while ($lo < $hi) {                       // binary search
            $mid = intdiv($lo + $hi, 2);
            if ($this->positions[$mid] < $h) { $lo = $mid + 1; } else { $hi = $mid; }
        }

        return $this->ring[$this->positions[$lo % count($this->positions)]];
    }
}

