private const COPIES = 8;

public function getHot(string $key): mixed
{
    // read one of 8 copies; each suffix hashes to a different node
    return $this->cache->get($key.'#'.random_int(0, self::COPIES - 1));
}

public function setHot(string $key, mixed $value): void
{
    for ($i = 0; $i < self::COPIES; $i++) {      // a write must update every copy
        $this->cache->set($key.'#'.$i, $value);
    }
}

public function run(string $month): void
{
    $lock = $this->lockFactory->createLock('payroll:'.$month, ttl: 60);

    if (!$lock->acquire()) {
        return;                       // another server is running this month's payroll
    }

    try {
        foreach ($this->employees->unpaidFor($month) as $employee) {
            $this->payroll->pay($employee, $month);
            $lock->refresh();         // still working: another 60 seconds
        }
    } finally {
        $lock->release();
    }
}

final class ReadConnectionPicker
{
    private const STICKY_SECONDS = 5;

    public function __construct(
        private readonly Connection $primary,               // default
        private readonly Connection $replicaConnection,     // doctrine: replica
    ) {
    }

    #[AsEventListener(event: KernelEvents::RESPONSE)]
    public function markWrite(ResponseEvent $event): void
    {
        if ($event->getRequest()->isMethodSafe()) {
            return;                       // nothing was written on GET/HEAD
        }
        $event->getResponse()->headers->setCookie(
            Cookie::create('last_write', (string) time())->withHttpOnly(true),
        );
    }

    public function forRead(Request $request): Connection
    {
        $lastWrite = (int) $request->cookies->get('last_write', '0');

        return time() - $lastWrite < self::STICKY_SECONDS
            ? $this->primary
            : $this->replicaConnection;
    }
}

public function replicaFor(int $userId): Connection
{
    // the same user always lands on the same replica, so a second refresh
    // can't show an older copy than the first one did
    return $this->replicas[$userId % count($this->replicas)];
}

protected function execute(InputInterface $in, OutputInterface $out): int
{
    $last = (int) $in->getOption('from');      // if it stopped, resume from here

    while (null !== ($max = $this->db->fetchOne(
        'SELECT max(id) FROM (
             SELECT id FROM orders WHERE id > ? ORDER BY id LIMIT 1000
         ) t',
        [$last],
    ))) {
        $this->db->executeStatement(
            'INSERT INTO orders_v2 (id, status, total_cents)
             SELECT id, status, total_cents FROM orders WHERE id > ? AND id <= ?
             ON CONFLICT (id) DO NOTHING',
            [$last, $max],
        );
        $last = (int) $max;
        $out->writeln('done up to '.$last);

        $lag = (float) $this->replicaConnection->fetchOne(
            'SELECT extract(epoch FROM now() - pg_last_xact_replay_timestamp())'
        );
        usleep($lag > 5 ? 5_000_000 : 200_000);   // if lag grows, back off
    }

    return Command::SUCCESS;
}

public function save(Order $order): void
{
    $this->oldStore->save($order);            // source of truth: the old one

    try {
        $this->newStore->save($order);       // upsert, so a missing row is created
    } catch (\Throwable $e) {
        // if the new one fails, don't block the order; we'll fix it later
        $this->logger->error('dual_write_failed', ['order' => $order->id, 'e' => $e]);
        $this->bus->dispatch(new RepairOrderCopy($order->id));
    }
}

#[Route('/accounts/{id}/withdraw', methods: ['POST'])]
public function withdraw(
    string $id,
    #[MapRequestPayload] WithdrawRequest $req,
): JsonResponse {
    try {
        // on the primary, with a majority; the key makes a retry safe
        $this->ledger->withdraw($id, $req->amountCents, $req->idempotencyKey);
    } catch (ConnectionException) {
        // CP: if we can't be sure, we don't hand out money
        return $this->json(['error' => 'try_later'], 503, ['Retry-After' => '5']);
    }

    return $this->json(['ok' => true]);
}

#[Route('/posts/{id}/likes', methods: ['GET'])]
public function likes(int $id): JsonResponse
{
    $count = $this->cache->get('likes:'.$id, function (ItemInterface $item) use ($id): int {
        $item->expiresAfter(30);              // 30 seconds stale is fine
        return $this->likes->countFromReplica($id);
    });

    return $this->json(['likes' => $count])->setPublic()->setMaxAge(30);
}

