public function merge(Cart $left, Cart $right): Cart
{
    $qty = [];
    foreach ([...$left->lines(), ...$right->lines()] as $line) {
        $qty[$line->sku] = max($qty[$line->sku] ?? 0, $line->qty);
    }

    // a tombstone: a sku removed on either side stays removed
    foreach ([...$left->removedSkus(), ...$right->removedSkus()] as $sku) {
        unset($qty[$sku]);
    }

    return Cart::fromQuantities($qty);        // nothing is lost by accident
}
